import{_ as a,c as e,o as i,a2 as t}from"./chunks/framework.PGES7OoM.js";const c=JSON.parse('{"title":"registerWithPasskey","description":"Register a new Curvy handle via a passkey PRF output.","frontmatter":{"editLink":false,"rawMarkdown":"# registerWithPasskey\\n\\nRegister a new Curvy handle via a passkey PRF output.\\n\\n## Import\\n\\n```ts\\nimport { registerWithPasskey } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst account = await registerWithPasskey({ handle, prfValue, credId });\\n```\\n\\n## Signature\\n\\n```ts\\nfunction registerWithPasskey(parameters: RegisterWithPasskeyParameters): Promise<CurvyAccount>\\n```\\n\\n## Returns\\n\\n`Promise<CurvyAccount>`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `handle`\\n\\n- **Type:** `CurvyId`\\n- **Required:** yes\\n\\nThe Curvy handle to register.\\n\\n```ts\\nconst result = await registerWithPasskey({\\n  handle, // [!code focus]\\n  prfValue,\\n});\\n```\\n\\n### `prfValue`\\n\\n- **Type:** `PasskeyPrfValue`\\n- **Required:** yes\\n\\nThe passkey PRF output used to derive the new account\'s Curvy keys.\\n\\n```ts\\nconst result = await registerWithPasskey({\\n  handle,\\n  prfValue, // [!code focus]\\n});\\n```\\n\\n### `credId`\\n\\n- **Type:** `ArrayBuffer`\\n- **Required:** no\\n\\nThe WebAuthn credential identifier associated with the passkey.\\n\\n```ts\\nconst result = await registerWithPasskey({\\n  handle,\\n  prfValue,\\n  credId, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = await registerWithPasskey({\\n  handle,\\n  prfValue,\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Authentication guide](/for-programmers/authentication)\\n- [`register`](/sdk/actions/auth/register) — Register a new Curvy handle from an account signature.\\n- [`registerWithPrivateKeys`](/sdk/actions/auth/registerWithPrivateKeys) — Register a new Curvy handle from raw spending and viewing private keys.\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/auth/registerWithPasskey.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/auth/registerWithPasskey.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/auth/registerWithPasskey.md","rawMarkdownTitle":"registerWithPasskey","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/auth/registerWithPasskey.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"auth","action":"registerWithPasskey"},"relativePath":"sdk/actions/auth/registerWithPasskey.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),n={name:"sdk/actions/auth/registerWithPasskey.md"};function r(h,s,l,o,p,d){return i(),e("div",null,[...s[0]||(s[0]=[t("",34)])])}const u=a(n,[["render",r]]);export{c as __pageData,u as default};
